import { readFileSync, writeFileSync } from "node:fs";
// A deterministic CSS Modules mapping lets the Worker SSR and Vite client use
// the same class names without importing a browser CSS loader into workerd.
const css = readFileSync("src/app/Movie.module.css", "utf8");
const names = [
  ...new Set(
    [...css.matchAll(/\.([A-Za-z_][A-Za-z0-9_-]*)/g)].map((m) => m[1]),
  ),
].sort();
const text =
  "// Generated by scripts/css-modules.ts; do not edit.\nexport default " +
  JSON.stringify(
    Object.fromEntries(names.map((n) => [n, `dm_${n}`])),
    null,
    2,
  ) +
  " as const;\n";
const output = "src/app/styles.generated.ts";
if (process.argv.includes("--check")) {
  if (readFileSync(output, "utf8") !== text)
    throw Error("CSS Modules mapping is stale. Run npm run styles:gen.");
} else writeFileSync(output, text);
